/**
 * The criteria a customer query is narrowed by: a free-text name filter and a
 * set of accepted statuses.
 *
 * <p>This is the "WHERE clause" the backend applies. Both parts are optional and
 * an omitted part matches everything, so {@link #EMPTY} selects the whole data
 * set.
 *
 * @param name     whitespace-separated terms; every term must occur in the
 *                 customer's first or last name, ignoring case and accents
 * @param statuses accepted statuses; empty means every status is accepted
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    /** Matches every customer. */
    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());

    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");
    private static final Pattern WHITESPACE = Pattern.compile("\\s+");

    public CustomerFilter {
        // Surrounding whitespace carries no meaning, and neither does the
        // difference between an unset filter and a blank one: normalising here
        // makes two filters that select the same rows equal to each other.
        name = (name == null) ? "" : name.strip();
        statuses = (statuses == null || statuses.isEmpty())
                ? Set.of()
                // An EnumSet iterates in declaration order, which is the order
                // the statuses appear in the view's URL.
                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
    }

    public CustomerFilter(String name) {
        this(name, Set.of());
    }

    /** {@code true} when this filter selects every customer. */
    public boolean isEmpty() {
        return name.isEmpty() && statuses.isEmpty();
    }

    /**
     * The name filter split into terms, normalised for comparison. Every term
     * has to match; an empty list matches every customer.
     */
    public List<String> terms() {
        if (name.isEmpty()) {
            return List.of();
        }
        List<String> terms = new ArrayList<>();
        for (String term : WHITESPACE.split(name)) {
            if (!term.isEmpty()) {
                terms.add(normalize(term));
            }
        }
        return List.copyOf(terms);
    }

    /**
     * Returns this filter as a predicate. The terms are normalised once per
     * call, not once per customer.
     */
    public Predicate<Customer> asPredicate() {
        List<String> terms = terms();
        Set<CustomerStatus> accepted = statuses;
        return customer -> (accepted.isEmpty() || accepted.contains(customer.status()))
                && matchesName(customer, terms);
    }

    private static boolean matchesName(Customer customer, List<String> terms) {
        if (terms.isEmpty()) {
            return true;
        }
        String firstName = normalize(customer.firstName());
        String lastName = normalize(customer.lastName());
        for (String term : terms) {
            if (!firstName.contains(term) && !lastName.contains(term)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Folds text down to what is compared: lower case, without accents. So
     * {@code makinen}, {@code MAKINEN} and {@code mäkinen} all normalise to the
     * same thing as {@code Mäkinen}.
