+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.MultiSelectComboBoxElement;
+
+/**
+ * The same view in a real (headless) browser: this is where the things a
+ * browserless test cannot see are checked — what the address bar says, and what
+ * typing costs the backend.
+ *
+ * <p>Named {@code *IT} so that it stays out of {@code mvn test}; run it with
+ * {@code mvn -o test -Dtest=CustomerFilterBrowserIT}.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerFilterBrowserIT extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    @Autowired
+    private CustomerRepository repository;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    @Test
+    void unfilteredListShowsEverybody() {
+        assertThat(summary()).hasText("Showing 500 of 500");
+        assertEquals(500, grid().getTotalRowCount());
+        assertEquals("/", path());
+    }
+
+    @Test
+    void typingNarrowsTheListWithoutOneQueryPerKeystroke() {
+        int expected = count("aaltonen");
+        queryLog.clear();
+
+        nameFilter().pressSequentially("aaltonen", new Locator.PressSequentiallyOptions().setDelay(40));
+
+        assertThat(summary()).hasText("Showing " + expected + " of 500");
+        assertEquals(expected, grid().getTotalRowCount());
+        assertEquals("/?name=aaltonen", path());
+
+        assertTrue(queryLog.countQueries().size() <= 2,
+                "Typing eight letters cost " + queryLog.countQueries().size()
+                        + " count queries: " + queryLog.countQueries());
+        assertTrue(queryLog.pageQueries().size() <= 2,
+                "Typing eight letters cost " + queryLog.pageQueries().size()
+                        + " page queries: " + queryLog.pageQueries());
+        queryLog.pageQueries().forEach(page -> assertTrue(
+                page.limit() <= CustomerRepository.MAX_PAGE_SIZE,
+                "A page query asked for " + page.limit() + " rows"));
+        assertTrue(queryLog.rowsFetched() <= CustomerRepository.MAX_PAGE_SIZE,
+                "Filtering pulled " + queryLog.rowsFetched() + " rows over");
+    }
+
+    @Test
+    void selectedStatusesEndUpInTheUrlInDeclarationOrder() {
+        // Selected the other way round; the URL lists them in declaration order.
+        statusFilter().selectItems("CLOSED", "ACTIVE");
+
+        int expected = count("", CustomerStatus.ACTIVE, CustomerStatus.CLOSED);
+        assertThat(summary()).hasText("Showing " + expected + " of 500");
+        assertEquals("/?status=ACTIVE,CLOSED", path());
+
+        statusFilter().deselectItems("CLOSED", "ACTIVE");
+        assertThat(summary()).hasText("Showing 500 of 500");
+        assertEquals("/", path(), "An empty filter must leave no parameters behind");
+    }
+
+    @Test
+    void bothFiltersEndUpInTheUrl() {
+        nameFilter().fill("vir");
+        statusFilter().selectItems("ACTIVE");
+
+        assertThat(summary()).hasText("Showing " + count("vir", CustomerStatus.ACTIVE) + " of 500");
+        assertEquals("/?name=vir&status=ACTIVE", path());
+    }
+
+    @Test
+    void openingAUrlWithAFilterAppliesAndShowsIt() {
+        int expected = count("vir", CustomerStatus.ACTIVE, CustomerStatus.CLOSED);
+        open("/?name=vir&status=ACTIVE,CLOSED");
+
+        assertThat(nameFilter()).hasValue("vir");
+        assertEquals(List.of("ACTIVE", "CLOSED"), statusFilter().getSelectedItems());
+        assertThat(summary()).hasText("Showing " + expected + " of 500");
+        assertEquals(expected, grid().getTotalRowCount());
+        assertEquals("/?name=vir&status=ACTIVE,CLOSED", path());
+    }
+
+    @Test
+    void typingDoesNotPileUpHistoryEntries() {
+        int entriesBefore = historyLength();
+
+        nameFilter().pressSequentially("aal", new Locator.PressSequentiallyOptions().setDelay(40));
+        assertThat(summary()).hasText("Showing " + count("aal") + " of 500");
+        nameFilter().pressSequentially("tonen", new Locator.PressSequentiallyOptions().setDelay(40));
