+        // address bar rather than for the summary.
+        page.waitForURL(getUrl() + "/?name=aaltonen");
+        assertEquals(entriesBefore, historyLength(),
+                "Filtering must update the address bar in place, not push history entries");
+    }
+
+    @Test
+    void sortingWorksWhileFiltered() {
+        nameFilter().fill("a");
+        assertThat(summary()).hasText("Showing " + count("a") + " of 500");
+
+        // Descending on the last name, sorted by the backend.
+        grid().findHeaderCellByText("Last name").orElseThrow().clickSort();
+        grid().findHeaderCellByText("Last name").orElseThrow().clickSort();
+        grid().findHeaderCellByText("Last name").orElseThrow().assertSortDescending();
+        grid().waitForGridToStopLoading();
+
+        String expected = repository.findAll(new CustomerFilter("a"), 0, 1,
+                        List.of(new com.example.customers.domain.CustomerSort("lastName", false)))
+                .getFirst().lastName();
+        assertThat(grid().findCell(0, 1).orElseThrow().getCellContentLocator()).hasText(expected);
+    }
+
+    // --- helpers -------------------------------------------------------------
+
+    private void open(String pathWithQuery) {
+        page.navigate(getUrl() + pathWithQuery);
+        page.waitForFunction(WAIT_FOR_VAADIN_SCRIPT);
+    }
+
+    /** The path and query of the address bar, without scheme, host and port. */
+    private String path() {
+        return page.url().substring(getUrl().length());
+    }
+
+    private Locator nameFilter() {
+        return page.locator("vaadin-text-field[placeholder='Filter by name'] input");
+    }
+
+    private MultiSelectComboBoxElement statusFilter() {
+        return MultiSelectComboBoxElement.getByLabel(page, "Status");
+    }
+
+    private GridElement grid() {
+        return GridElement.get(page);
+    }
+
+    private Locator summary() {
+        return page.locator("span").filter(new Locator.FilterOptions().setHasText("Showing"));
+    }
+
+    private int historyLength() {
+        return ((Number) page.evaluate("() => window.history.length")).intValue();
+    }
+
+    private int count(String name, CustomerStatus... statuses) {
+        return repository.count(new CustomerFilter(name, Set.of(statuses)));
